<?php
declare(strict_types=1);
namespace BYPCMS\Core;
require_once __DIR__.'/Content.php';
require_once __DIR__.'/Journal.php';

/** Corporate presentation over the shared Business content, CRM and form contract. */
final class Corporate {
    public static function published(array $page):bool {
        $status=$page['status']??'published';$date=$page['published_at']??'';
        return in_array($status,['published','scheduled'],true)&&(!$date?$status==='published':strtotime($date.' UTC')!==false&&strtotime($date.' UTC')<=time());
    }
    public static function imageSources(string $url):string {
        if(preg_match('#^/themes/corporate/assets/(headquarters|workspace|team|person-[1-3])\.webp$#D',$url,$m)){$stem=substr($url,0,-5);$full=str_starts_with($m[1],'person-')?1120:1440;return ' srcset="'.Content::e(Content::asset($stem.'-480.webp')).' 480w, '.Content::e(Content::asset($stem.'-960.webp')).' 960w, '.Content::e(Content::asset($url)).' '.$full.'w" sizes="(max-width:600px) 100vw, (max-width:1000px) 50vw, 680px"';}
        return Content::imageSet($url);
    }
    private static function query(string $key,int $limit=100):string {
        if(!is_scalar($_GET[$key]??''))throw new \RuntimeException('Проверьте параметры поиска и фильтра.');
        return mb_substr(trim((string)($_GET[$key]??'')),0,$limit);
    }
    public static function render(array $pages,array $settings,string $path,string $base='',array $options=[]):void {
        $e=[Content::class,'e'];$path=trim($path,'/');$snapshot=$options['snapshot']??'';$preview=!empty($options['preview']);
        $pages=array_values(array_filter($pages,fn($p)=>in_array($p['kind']??'page',['service','project','person','page'],true)&&($preview||self::published($p))));
        foreach($pages as &$record)$record+=['id'=>0,'kind'=>'page','excerpt'=>'','content'=>'','cover'=>'','blocks'=>[]];unset($record);
        $find=static function(string $slug)use($pages){foreach($pages as $p)if(trim($p['slug'],'/')===$slug)return $p;return null;};
        $services=array_values(array_filter($pages,fn($p)=>$p['kind']==='service'));$projects=array_values(array_filter($pages,fn($p)=>$p['kind']==='project'));$team=array_values(array_filter($pages,fn($p)=>$p['kind']==='person'));
        $href=static fn(string $p,array $q=[])=>$base.$p.(($q+($snapshot?['snapshot'=>$snapshot]:[]))?'?'.http_build_query($q+($snapshot?['snapshot'=>$snapshot]:[])):'');
        $asset=static fn(string $p)=>Content::asset('/themes/corporate/'.$p);
        $routes=[''=>'home','services'=>'services','projects'=>'projects','team'=>'team','contact'=>'contact','search'=>'search','request-success'=>'success'];$page=$path!==''?$find($path):null;$mode=$routes[$path]??($page?'detail':'404');
        if($mode==='success'&&empty($options['receipt']))$mode='404';
        $error='';$q='';$service=0;$number=1;
        try{$q=self::query('q');foreach(['service','page'] as $key){$value=self::query($key,12);if($value!==''&&(!ctype_digit($value)||strlen($value)>7))throw new \RuntimeException('Укажите корректный номер страницы или направление.');if($key==='service')$service=(int)$value;else $number=max(1,(int)$value);}}catch(\RuntimeException $x){$error=$x->getMessage();}
        $http=$options['http_status']??($error?400:($mode==='404'?404:200));http_response_code($http);
        header('Content-Type: text/html; charset=utf-8');header('X-Content-Type-Options: nosniff');header("Content-Security-Policy: default-src 'self'; img-src 'self' https: data:; style-src 'self' 'unsafe-inline'; font-src 'self'; script-src 'self'; frame-ancestors 'self'; base-uri 'none'; form-action 'self'");
        if($base||$preview||in_array($mode,['contact','success','search'],true)||$http!==200){header('X-Robots-Tag: noindex, nofollow');header('Cache-Control: no-store');}
        $name=$settings['site_name']??'Corporate';$titles=['home'=>$settings['tagline']??'Решения, на которые можно опереться.','services'=>'Услуги и решения','projects'=>'Проекты и кейсы','team'=>'Команда','contact'=>'Обсудим вашу задачу','search'=>'Поиск по сайту','success'=>'Заявка сохранена','404'=>'Страница не найдена'];
        $title=$mode==='detail'?(($page['seo_title']??'')?:$page['title']):($titles[$mode]??$name);$description=$mode==='detail'?(($page['seo_description']??'')?:$page['excerpt']):($settings['tagline']??'Комплексный подход к задачам бизнеса.');
        $accent=preg_match('/^#[0-9a-f]{6}$/i',$settings['accent']??'')?$settings['accent']:'#2454d5';$home=$find('home');$about=$find('about');
        $hero=$home['cover']??'';if(!$hero){$featured=array_values(array_filter($projects,fn($p)=>!empty($p['featured'])));$hero=$featured[0]['cover']??$projects[0]['cover']??$asset('assets/headquarters.webp');}
        $canonical=Content::url($page['canonical']??'')?:rtrim($settings['site_url']??'','/').$base.'/'.($path?$path.'/':'');
        $image=static function(array $p,bool $eager=false)use($e){$src=Content::imageUrl($p['cover']??'');return $src?'<img src="'.$e(Content::asset($src)).'"'.self::imageSources($src).' alt="'.$e($p['cover_alt']??$p['title']).'" width="1200" height="800" decoding="async" '.($eager?'fetchpriority="high"':'loading="lazy"').'>':'<div class="co-noimage">Изображение не добавлено</div>';};
        $cards=static function(array $rows,string $kind='project')use($e,$href,$image){foreach($rows as $p){$cardKind=$kind==='auto'?($p['kind']==='service'?'service':($p['kind']==='person'?'person':($p['kind']==='project'?'project':'page'))):$kind; ?>
            <article class="co-card co-card-<?= $e($cardKind) ?>"><?php if($cardKind!=='service'): ?><a class="co-card-image" href="<?= $e($href('/'.$p['slug'].'/')) ?>"><?= $image($p) ?><span aria-hidden="true">↗</span></a><?php endif ?><div class="co-card-body"><?php if($cardKind==='project'): ?><small><?= $e($p['location']??'ПРОЕКТ') ?></small><?php elseif($cardKind==='person'): ?><small><?= $e($p['role']??'КОМАНДА') ?></small><?php else: ?><span class="co-service-icon" aria-hidden="true">↗</span><?php endif ?><h3><a href="<?= $e($href('/'.$p['slug'].'/')) ?>"><?= $e($p['title']) ?></a></h3><p><?= $e($p['excerpt']) ?></p><a class="co-text-link" href="<?= $e($href('/'.$p['slug'].'/')) ?>"><?= $cardKind==='service'?'Подробнее об услуге':($cardKind==='person'?'Познакомиться':($cardKind==='page'?'Подробнее':'Смотреть кейс')) ?> <span aria-hidden="true">↗</span></a></div></article>
        <?php }};
        ?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $e($title.' — '.$name) ?></title><meta name="description" content="<?= $e($description) ?>"><link rel="canonical" href="<?= $e($canonical) ?>"><meta property="og:title" content="<?= $e($title) ?>"><meta property="og:description" content="<?= $e($description) ?>"><meta property="og:type" content="website"><meta property="og:url" content="<?= $e($canonical) ?>"><?php $socialImage=Content::imageUrl($page['cover']??$hero);if($socialImage): ?><meta property="og:image" content="<?= $e(preg_match('#^https?://#',$socialImage)?$socialImage:rtrim($settings['site_url']??'','/').Content::asset($socialImage)) ?>"><?php endif ?><?php if(!empty($page['noindex'])): ?><meta name="robots" content="noindex,follow"><?php endif ?><link rel="stylesheet" href="<?= $e($asset('corporate.css')) ?>?v=1.0.0"><script src="<?= $e($asset('corporate.js')) ?>?v=1.0.0" defer></script><?php if(($settings['font']??'')!=='system'): ?><link rel="preload" as="font" type="font/woff2" href="<?= $e($asset('assets/manrope.woff2')) ?>" crossorigin><?php endif ?><style>:root{--co-accent:<?= $e($accent) ?>;--co-font:<?= ($settings['font']??'')==='system'?'system-ui':'CorporateSans' ?>;--co-heading:<?= ($settings['heading_font']??'')==='georgia'?'Georgia,serif':'var(--co-font)' ?>}</style></head><body class="co-site co-view-<?= $e($mode) ?>"><a class="co-skip" href="#main">К содержанию</a>
        <?php if(!empty($options['demo'])): ?><div class="co-demo">BYPCMS Business / Corporate <span>Демонстрационная компания · тестовые заявки без отправки писем</span></div><?php endif ?>
        <?php if($preview): ?><div class="co-demo">Предпросмотр · изменения не опубликованы <a id="preview-close" href="/manage/">Закрыть ×</a></div><script src="<?= $e(Content::asset('/themes/journal/preview.js')) ?>" defer></script><?php endif ?>
        <header class="co-header"><div class="co-wrap co-header-inner"><a class="co-logo" href="<?= $e($href('/')) ?>"><?php if(!empty($settings['logo'])): ?><img src="<?= $e(Content::imageUrl($settings['logo'])) ?>" alt="<?= $e($name) ?>"><?php else: ?><span class="co-logo-symbol" aria-hidden="true"><?= $e(mb_strtoupper(mb_substr($name,0,1))) ?></span><span><?= $e($name) ?><small>РЕШЕНИЯ ДЛЯ БИЗНЕСА</small></span><?php endif ?></a><button class="co-menu-toggle" type="button" aria-expanded="false" aria-controls="corporate-nav" aria-label="Открыть меню">☰</button><nav id="corporate-nav" aria-label="Основное меню"><?php foreach(['/services/'=>'Услуги','/projects/'=>'Проекты','/about/'=>'Компания','/team/'=>'Команда','/contact/'=>'Контакты'] as $url=>$label): if($url==='/about/'&&!$about)continue; ?><a href="<?= $e($href($url)) ?>" <?= $path===trim($url,'/')?'aria-current="page"':'' ?>><?= $label ?></a><?php endforeach ?><?= Journal::menu($settings['menu']??[]) ?><a class="co-search-link" href="<?= $e($href('/search/')) ?>" aria-label="Поиск по сайту"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg></a></nav><a class="co-button co-header-cta" href="<?= $e($href('/contact/')) ?>">Обсудить задачу <span>↗</span></a></div></header>
